   202|    ownerId,
   203|    createdAt: nowIso(),
   204|    updatedAt: nowIso(),
   205|    executionState: 'PENDING_APPROVAL',
   206|    originalQuestion: input.originalQuestion,
   207|    actionType: input.actionType,
   208|    resource: input.resource,
   209|    operation: input.operation,
   210|    authorizationRequired: input.authorizationRequired,
   211|    authorizationStatus: input.authorizationRequired ? 'pending' : 'not_required',
   212|    languagePreference: input.languagePreference ?? state.languagePreference,
   213|    lastResultSummary: null,
   214|    lastError: null,
   215|    traceId: null,
   216|    metadata: input.metadata ?? {},
   217|  };
   218|  const actions = [...state.actions, action];
   219|  // Keep only the most recent 20 actions per conversation to bound size.
