   372|    let marker: string | null = null;
   373|    try {
   374|      const j = await r.json() as Record<string, unknown>;
   375|      if (typeof j?.deploymentMarker === 'string') marker = j.deploymentMarker;
   376|      else if (typeof j?.marker === 'string') marker = j.marker;
   377|    } catch {
   378|      // body may be plain text — ignore
   379|    }
   380|    return { baseUrl, status: r.status, ok: r.ok, marker, error: null, durationMs: Date.now() - started };
   381|  } catch (err) {
   382|    return { baseUrl, status: null, ok: false, marker: null, error: err instanceof Error ? err.message : 'network_error', durationMs: Date.now() - started };
