   386|/**
   387| * POST /api/ivx/autonomy/deploy/approve-and-run
   388| *
   389| * One-tap autonomous owner-approved deploy. Verifies the signed-in owner via
   390| * the Supabase bearer attached to the request, triggers a Render deploy of
   391| * the latest commit, polls until terminal status, then probes production
   392| * `/health`. Returns full proof. Never echoes secrets.
   393| *
   394| * Body: { clearCache?: boolean; pollTimeoutMs?: number }
   395| */
   396|export async function handleIVXAutonomyDeployApproveAndRunRequest(request: Request): Promise<Response> {
   397|  const startedAt = new Date().toISOString();
   398|  try {
   399|    const ownerContext = await assertIVXOwnerOnly(request);
   400|    const body = readObjectInput(await request.json().catch(() => ({})));
   401|    const clearCache = body.clearCache === true ? 'clear' : 'do_not_clear';
   402|    const pollTimeoutMs = typeof body.pollTimeoutMs === 'number' && Number.isFinite(body.pollTimeoutMs)
   403|      ? Math.min(Math.max(body.pollTimeoutMs, 30_000), 8 * 60_000)
   404|      : 5 * 60_000;
   405|
   406|    const { apiKey, serviceId } = await readRenderCreds();
   407|    if (!apiKey || !serviceId) {
   408|      return ownerOnlyJson({
   409|        ok: false,
   410|        marker: IVX_AUTONOMY_MARKER,
   411|        stage: 'preflight',
   412|        error: 'missing_render_credentials',
   413|        renderApiKeyConfigured: Boolean(apiKey),
   414|        renderServiceIdConfigured: Boolean(serviceId),
   415|        hint: 'Backend runtime cannot read RENDER_API_KEY / RENDER_SERVICE_ID from env or Owner Variables.',
   416|      }, 503);
   417|    }
   418|
   419|    const ownerEmail = typeof ownerContext.email === 'string' ? ownerContext.email : null;
   420|    const ownerEmailMasked = ownerEmail
   421|      ? `${ownerEmail.slice(0, 2)}***@${ownerEmail.split('@')[1] ?? 'unknown'}`
   422|      : null;
   423|    const approvalProof = {
   424|      approved: true,
   425|      ownerUserId: ownerContext.userId,
   426|      ownerEmailMasked,
   427|      ownerRole: ownerContext.role,
   428|      guardMode: ownerContext.guardMode,
   429|      approvedAt: startedAt,
   430|      mechanism: 'in_app_one_tap_owner_session',
   431|    };
   432|
   433|    // Stage 1 — trigger Render deploy
   434|    let triggerStatus = 0;
   435|    let triggerOk = false;
   436|    let triggerParsed: unknown = null;
   437|    try {
   438|      const r = await fetch(`https://api.render.com/v1/services/${encodeURIComponent(serviceId)}/deploys`, {
   439|        method: 'POST',
   440|        headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json', Accept: 'application/json' },
   441|        body: JSON.stringify({ clearCache }),
   442|      });
   443|      triggerStatus = r.status;
   444|      triggerOk = r.ok;
   445|      const text = await r.text();
   446|      if (text) {
   447|        try { triggerParsed = JSON.parse(text); } catch { triggerParsed = { raw: text.slice(0, 2000) }; }
   448|      }
   449|    } catch (err) {
   450|      return ownerOnlyJson({
   451|        ok: false,
   452|        marker: IVX_AUTONOMY_MARKER,
   453|        stage: 'render_trigger',
   454|        approvalProof,
   455|        error: err instanceof Error ? err.message : 'render_trigger_network_error',
   456|      }, 502);
   457|    }
   458|
   459|    if (!triggerOk) {
   460|      return ownerOnlyJson({
   461|        ok: false,
   462|        marker: IVX_AUTONOMY_MARKER,
   463|        stage: 'render_trigger',
   464|        approvalProof,
   465|        renderHttpStatus: triggerStatus,
   466|        renderResponse: triggerParsed,
   467|      }, triggerStatus >= 400 && triggerStatus < 600 ? triggerStatus : 502);
   468|    }
   469|
   470|    const triggered = (triggerParsed && typeof triggerParsed === 'object' && 'deploy' in (triggerParsed as Record<string, unknown>))
   471|      ? ((triggerParsed as { deploy: RenderDeployStatusEntry }).deploy)
   472|      : (triggerParsed as RenderDeployStatusEntry | null);
   473|    const deployId = triggered && typeof triggered.id === 'string' ? triggered.id : null;
   474|
   475|    if (!deployId) {
   476|      return ownerOnlyJson({
   477|        ok: false,
   478|        marker: IVX_AUTONOMY_MARKER,
   479|        stage: 'render_trigger',
   480|        approvalProof,
   481|        error: 'render_did_not_return_deploy_id',
   482|        renderResponse: triggerParsed,
   483|      }, 502);
   484|    }
   485|
   486|    // Stage 2 — poll until terminal
   487|    const polled = await pollRenderDeploy(apiKey, serviceId, deployId, pollTimeoutMs);
   488|    const finalStatus = String(polled.entry?.status ?? triggered?.status ?? '').toLowerCase();
   489|    const deployLive = finalStatus.includes('live');
   490|    const deployFailed = ['build_failed', 'update_failed', 'canceled', 'pre_deploy_failed'].some((s) => finalStatus.includes(s));
   491|
   492|    // Stage 3 — production health probe (only meaningful when deploy is live)
   493|    const productionProbe = deployLive ? await probeProductionHealth() : null;
   494|
   495|    const finishedAt = new Date().toISOString();
   496|    const overallOk = deployLive && productionProbe?.ok === true;
   497|
   498|    return ownerOnlyJson({
   499|      ok: overallOk,
   500|      marker: IVX_AUTONOMY_MARKER,
   501|      stage: deployFailed ? 'render_failed' : !polled.terminal ? 'render_in_progress' : overallOk ? 'verified_live' : 'verification_failed',
   502|      approvalProof,
   503|      deploy: {
   504|        id: deployId,
   505|        status: polled.entry?.status ?? triggered?.status ?? null,
   506|        commitSha: polled.entry?.commit?.id ?? triggered?.commit?.id ?? null,
   507|        commitMessage: polled.entry?.commit?.message ?? triggered?.commit?.message ?? null,
   508|        createdAt: polled.entry?.createdAt ?? triggered?.createdAt ?? null,
   509|        finishedAt: polled.entry?.finishedAt ?? null,
   510|        failureReason: polled.entry?.failureReason ?? null,
   511|        pollCount: polled.pollCount,
   512|        reachedTerminal: polled.terminal,
   513|      },
   514|      clearCache,
   515|      productionProbe,
   516|      rollback: {
   517|        available: true,
   518|        route: 'POST /api/ivx/autonomy/deploy/rollback',
   519|      },
   520|      timing: { startedAt, finishedAt },
   521|      policy: { ownerApprovalRequired: true, twoFactorImplemented: false, secretsExposed: false },
   522|    }, overallOk ? 200 : deployFailed ? 502 : 200);
   523|  } catch (error) {
   524|    return errorResponse(error, 401);
   525|  }
   526|}
