   569|function parseGithubRepoSlug(value: string): string {
   570|  const normalized = (value || '').trim();
   571|  if (!normalized) return '';
   572|  if (/^[^/\s]+\/[^/\s]+$/.test(normalized)) return normalized.replace(/\.git$/i, '');
   573|  const m = normalized.match(/github\.com[/:]([^/\s]+)\/([^/.\s]+)(?:\.git)?/i);
   574|  return m ? `${m[1]}/${m[2]}` : '';
   575|}
