   216|      value
   217|        .map((v) => asTrimmedString(v).toLowerCase())
   218|        .filter(Boolean),
   219|    ),
   220|  );
   221|}
   222|
   223|async function ensureDir(): Promise<void> {
   224|  await mkdir(DIR, { recursive: true });
   225|}
   226|
   227|async function readState(): Promise<ScopedMemoryRecord[]> {
   228|  if (isDurableStoreConfigured()) {
   229|    try {
   230|      const rows = await readDurableJson<ScopedMemoryRecord[]>(STATE_PATH, []);
   231|      return Array.isArray(rows) ? rows : [];
   232|    } catch {
   233|      return [];
   234|    }
   235|  }
   236|  try {
   237|    const raw = await readFile(STATE_PATH, 'utf8');
   238|    const parsed = JSON.parse(raw) as unknown;
   239|    return Array.isArray(parsed) ? (parsed as ScopedMemoryRecord[]) : [];
   240|  } catch {
   241|    return [];
   242|  }
   243|}
   244|
   245|async function writeState(records: ScopedMemoryRecord[]): Promise<void> {
   246|  const bounded = records.slice(-5000);
   247|  if (isDurableStoreConfigured()) {
   248|    await writeDurableJson(STATE_PATH, bounded);
   249|    return;
   250|  }
   251|  await ensureDir();
   252|  const tmp = path.join(DIR, `scoped-memory-${randomUUID()}.tmp`);
   253|  await writeFile(tmp, JSON.stringify(bounded, null, 2), 'utf8');
   254|  try {
   255|    await rename(tmp, STATE_PATH);
   256|  } catch (error) {
   257|    const code = (error as { code?: string }).code;
   258|    if (code === 'ENOENT') {
   259|      await ensureDir();
   260|      await rename(tmp, STATE_PATH);
   261|      return;
   262|    }
   263|    throw error;
   264|  }
   265|}
   266|
   267|async function appendEvent(event: Record<string, unknown>): Promise<void> {
   268|  if (isDurableStoreConfigured()) {
   269|    try {
   270|      await appendDurableEvent(LOG_PATH, event);
   271|    } catch {
   272|      // Forensic log is best-effort.
   273|    }
   274|    return;
   275|  }
   276|  try {
   277|    await ensureDir();
   278|    await appendFile(LOG_PATH, `${JSON.stringify(event)}\n`, 'utf8');
   279|  } catch {
   280|    // Best-effort.
   281|  }
   282|}
   283|
   284|function enqueueWrite<T>(task: () => Promise<T>): Promise<T> {
   285|  const run = writeChain.then(task, task);
   286|  writeChain = run.then(
   287|    () => undefined,
   288|    () => undefined,
   289|  );
   290|  return run;
   291|}
   292|
   293|// ─── Isolation Enforcement ────────────────────────────────────────
   294|
   295|export type MemoryAccessContext = {
   296|  /** The agent requesting access. */
   297|  agentId: string;
   298|  /** The company the agent is assigned to (null = unassigned). */
   299|  companyId: string | null;
   300|  /** The task the agent is currently assigned to (null = no task). */
   301|  taskId: string | null;
   302|  /** True if the owner is requesting access. */
   303|  isOwner: boolean;
   304|};
   305|
   306|export type AccessCheckResult = { allowed: boolean; reason: string };
   307|
   308|/**
   309| * Enforce isolation rules — Agent A cannot read Agent B's private memory,
   310| * Company A cannot read Company B's private memory, etc.
   311| */
   312|export function checkMemoryAccess(
   313|  record: ScopedMemoryRecord,
   314|  ctx: MemoryAccessContext,
   315|): AccessCheckResult {
   316|  // Owner can access everything.
   317|  if (ctx.isOwner) {
   318|    return { allowed: true, reason: 'owner access' };
   319|  }
   320|
   321|  switch (record.layer) {
   322|    case 'task': {
   323|      // Task memory is readable by any agent assigned to that task.
   324|      if (record.scopeId === ctx.taskId) {
   325|        return { allowed: true, reason: 'task assignment match' };
   326|      }
   327|      return { allowed: false, reason: 'agent is not assigned to this task' };
   328|    }
   329|
   330|    case 'agent': {
   331|      // Agent memory is readable only by that agent.
   332|      if (record.scopeId === ctx.agentId) {
   333|        return { allowed: true, reason: 'agent self access' };
   334|      }
   335|      return { allowed: false, reason: 'agent cannot read another agent private memory' };
   336|    }
   337|
   338|    case 'company': {
   339|      // Company memory is readable only by agents assigned to the same company.
   340|      if (record.scopeId === ctx.companyId) {
   341|        return { allowed: true, reason: 'company assignment match' };
   342|      }
   343|      return { allowed: false, reason: 'agent cannot read another company private memory' };
   344|    }
   345|
   346|    case 'enterprise': {
   347|      // Enterprise memory is global and readable by all agents (read-only).
   348|      return { allowed: true, reason: 'enterprise memory is globally readable' };
   349|    }
   350|
   351|    default:
   352|      return { allowed: false, reason: `unknown layer: ${record.layer}` };
   353|  }
   354|}
   355|
   356|/**
   357| * Enforce write isolation — only the owning agent, company member, or owner
   358| * can modify their own memory. Enterprise memory is owner-write-only.
   359| */
   360|export function checkMemoryWriteAccess(
   361|  record: ScopedMemoryRecord,
   362|  ctx: MemoryAccessContext,
   363|): AccessCheckResult {
   364|  // Owner can write everything.
   365|  if (ctx.isOwner) {
   366|    return { allowed: true, reason: 'owner write access' };
   367|  }
   368|
   369|  switch (record.layer) {
   370|    case 'task': {
   371|      // Any agent assigned to the task can write task memory.
   372|      if (record.scopeId === ctx.taskId) {
   373|        return { allowed: true, reason: 'task assignment write' };
   374|      }
   375|      return { allowed: false, reason: 'agent is not assigned to this task' };
   376|    }
   377|
   378|    case 'agent': {
   379|      // Agent can write only its own memory.
   380|      if (record.scopeId === ctx.agentId) {
   381|        return { allowed: true, reason: 'agent self write' };
   382|      }
   383|      return { allowed: false, reason: 'agent cannot modify another agent memory' };
   384|    }
   385|
   386|    case 'company': {
   387|      // Any agent in the same company can write company memory.
   388|      if (record.scopeId === ctx.companyId) {
   389|        return { allowed: true, reason: 'company member write' };
   390|      }
   391|      return { allowed: false, reason: 'agent cannot modify another company memory' };
   392|    }
   393|
   394|    case 'enterprise': {
   395|      // Enterprise memory is owner-write-only.
   396|      return { allowed: false, reason: 'enterprise memory is owner-write-only' };
   397|    }
   398|
   399|    default:
   400|      return { allowed: false, reason: `unknown layer: ${record.layer}` };
   401|  }
   402|}
   403|
   404|// ─── CRUD Operations ──────────────────────────────────────────────
   405|
   406|export type CreateScopedMemoryInput = {
   407|  layer: MemoryLayer;
   408|  scopeId?: string;
   409|  kind: MemoryKind;
   410|  content: string;
   411|  source: string;
   412|  sourceType?: 'file' | 'api' | 'owner' | 'agent' | 'system';
   413|  sourceLabel?: string;
   414|  tags?: string[];
   415|  expiresAt?: string | null;
   416|  sourceFilePath?: string | null;
   417|  sourceCommitSha?: string | null;
   418|  /** Access context for write-permission check. */
   419|  writeCtx?: MemoryAccessContext | null;
   420|};
   421|
   422|export type CreateResult =
   423|  | { ok: true; record: ScopedMemoryRecord }
   424|  | { ok: false; error: string };
   425|
   426|/**
   427| * Create a scoped memory record. Validates input, rejects secrets, enforces
   428| * write isolation, and persists durably (survives restarts).
   429| */
   430|export async function createScopedMemory(input: CreateScopedMemoryInput): Promise<CreateResult> {
   431|  const validation = validateScopedMemoryInput(input);
   432|  if (!validation.ok) return validation;
   433|
   434|  const scopeId = input.layer === 'enterprise' ? '' : asTrimmedString(input.scopeId);
   435|
   436|  const now = nowIso();
   437|  const record: ScopedMemoryRecord = {
   438|    id: createId(),
   439|    layer: input.layer,
   440|    scopeId,
   441|    kind: input.kind,
   442|    content: asTrimmedString(input.content),
   443|    source: asTrimmedString(input.source),
   444|    sourceType: input.sourceType ?? 'system',
   445|    sourceLabel: asTrimmedString(input.sourceLabel) || asTrimmedString(input.source),
   446|    createdAt: now,
   447|    updatedAt: now,
   448|    expiresAt: input.expiresAt ?? null,
   449|    supersededById: null,
   450|    revoked: false,
   451|    revokedAt: null,
   452|    revokedBy: null,
   453|    tags: asTagArray(input.tags),
   454|    sourceFilePath: input.sourceFilePath ?? null,
   455|    sourceCommitSha: input.sourceCommitSha ?? null,
   456|  };
   457|
   458|  // Enforce write access if context provided.
   459|  if (input.writeCtx) {
   460|    const writeCheck = checkMemoryWriteAccess(record, input.writeCtx);
   461|    if (!writeCheck.allowed) {
   462|      return { ok: false, error: `Write denied: ${writeCheck.reason}` };
   463|    }
   464|  }
   465|
   466|  return enqueueWrite(async () => {
   467|    const records = await readState();
   468|    records.push(record);
   469|    await writeState(records);
   470|    await appendEvent({ type: 'create', record, at: now });
   471|    return { ok: true as const, record };
   472|  });
   473|}
   474|
   475|/**
   476| * Retrieve scoped memory with isolation enforcement.
   477| * Agent A cannot read Agent B's private memory.
   478| * Company A cannot read Company B's private memory.
   479| */
   480|export async function retrieveScopedMemory(
   481|  query: ScopedMemoryQuery,
   482|  accessCtx: MemoryAccessContext,
   483|): Promise<{ records: ScopedMemoryRecord[]; denied: number }> {
   484|  const records = await readState();
   485|  const filtered = filterScopedMemoryRecords(records, query);
   486|
   487|  const allowed: ScopedMemoryRecord[] = [];
   488|  let denied = 0;
   489|  for (const record of filtered) {
   490|    const check = checkMemoryAccess(record, accessCtx);
   491|    if (check.allowed) {
   492|      allowed.push(record);
   493|    } else {
   494|      denied++;
   495|    }
   496|  }
   497|
   498|  return { records: allowed, denied };
   499|}
   500|
   501|/** Pure filter function — extracted for unit testing (no isolation check). */
   502|export function filterScopedMemoryRecords(
   503|  records: readonly ScopedMemoryRecord[],
   504|  query: ScopedMemoryQuery = {},
   505|): ScopedMemoryRecord[] {
   506|  const now = new Date();
   507|  let results = [...records];
   508|
   509|  // Filter revoked (unless explicitly included).
   510|  if (!query.includeRevoked) {
   511|    results = results.filter((r) => !r.revoked);
   512|  }
   513|
   514|  // Filter superseded (unless explicitly included).
   515|  if (!query.includeSuperseded) {
   516|    results = results.filter((r) => r.supersededById === null);
   517|  }
   518|
   519|  // Filter expired (unless explicitly included).
   520|  if (!query.includeExpired) {
   521|    results = results.filter((r) => {
   522|      if (!r.expiresAt) return true;
   523|      return new Date(r.expiresAt) > now;
   524|    });
   525|  }
   526|
   527|  if (query.layer) {
   528|    results = results.filter((r) => r.layer === query.layer);
   529|  }
   530|
   531|  if (query.scopeId !== undefined) {
   532|    results = results.filter((r) => r.scopeId === query.scopeId);
   533|  }
   534|
   535|  if (query.kind) {
   536|    results = results.filter((r) => r.kind === query.kind);
   537|  }
   538|
   539|  if (query.tags && query.tags.length > 0) {
   540|    const tags = new Set(query.tags.map((t) => t.toLowerCase()));
   541|    results = results.filter((r) => r.tags.some((t) => tags.has(t)));
   542|  }
   543|
   544|  if (query.search) {
   545|    const search = query.search.toLowerCase();
   546|    results = results.filter((r) =>
   547|      r.content.toLowerCase().includes(search) ||
   548|      r.tags.some((t) => t.includes(search)) ||
   549|      r.sourceLabel.toLowerCase().includes(search),
   550|    );
   551|  }
   552|
   553|  // Sort by most recently updated.
   554|  results.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
   555|
   556|  return results.slice(0, query.limit || 100);
   557|}
   558|
   559|// ─── Supersede Logic ──────────────────────────────────────────────
   560|
   561|/**
   562| * Supersede a memory record — marks the old record as superseded by a new one.
   563| * This implements "old context must not override current owner instructions."
   564| */
   565|export async function supersedeMemory(
   566|  oldId: string,
   567|  newRecord: ScopedMemoryRecord,
   568|  writeCtx?: MemoryAccessContext | null,
   569|): Promise<{ ok: true; oldRecord: ScopedMemoryRecord | null; newRecord: ScopedMemoryRecord } | { ok: false; error: string }> {
   570|  return enqueueWrite(async () => {
   571|    const records = await readState();
   572|    const oldIndex = records.findIndex((r) => r.id === oldId);
   573|    if (oldIndex < 0) {
   574|      return { ok: false as const, error: 'Record to supersede not found.' };
   575|    }
   576|    const oldRecord = records[oldIndex]!;
   577|
   578|    // Enforce write access on the old record.
   579|    if (writeCtx) {
   580|      const writeCheck = checkMemoryWriteAccess(oldRecord, writeCtx);
   581|      if (!writeCheck.allowed) {
   582|        return { ok: false as const, error: `Write denied: ${writeCheck.reason}` };
   583|      }
   584|    }
   585|
   586|    // Mark old record as superseded.
   587|    records[oldIndex] = {
   588|      ...oldRecord,
   589|      supersededById: newRecord.id,
   590|      updatedAt: nowIso(),
   591|    };
   592|
   593|    // Add the new record.
   594|    records.push(newRecord);
   595|
   596|    await writeState(records);
   597|    await appendEvent({ type: 'supersede', oldId, newRecord, at: newRecord.createdAt });
   598|    return { ok: true as const, oldRecord: records[oldIndex]!, newRecord };
   599|  });
   600|}
   601|
   602|/**
   603| * Create a superseding record — convenience function that creates a new record
   604| * and marks the old one as superseded in one operation.
   605| */
   606|export async function createSupersedingRecord(
   607|  oldId: string,
   608|  input: CreateScopedMemoryInput,
   609|): Promise<CreateResult> {
   610|  const validation = validateScopedMemoryInput(input);
   611|  if (!validation.ok) return validation;
   612|
   613|  const createResult = await createScopedMemory(input);
   614|  if (!createResult.ok) return createResult;
   615|
   616|  const supersedeResult = await supersedeMemory(oldId, createResult.record, input.writeCtx ?? null);
   617|  if (!supersedeResult.ok) {
   618|    // New record was created but supersede failed — return the new record anyway.
   619|    return { ok: true, record: createResult.record };
   620|  }
   621|  return { ok: true, record: createResult.record };
   622|}
   623|
   624|// ─── Revocation ───────────────────────────────────────────────────
   625|
   626|/**
   627| * Revoke a memory record — takes effect immediately.
   628| * Revoked records are excluded from all queries unless includeRevoked is true.
   629| */
   630|export async function revokeMemory(
   631|  id: string,
   632|  revokedBy: string,
   633|  writeCtx?: MemoryAccessContext | null,
   634|): Promise<{ ok: true; record: ScopedMemoryRecord } | { ok: false; error: string }> {
   635|  return enqueueWrite(async () => {
   636|    const records = await readState();
   637|    const index = records.findIndex((r) => r.id === id);
   638|    if (index < 0) {
   639|      return { ok: false as const, error: 'Record not found.' };
   640|    }
   641|    const record = records[index]!;
   642|
   643|    if (writeCtx) {
   644|      const writeCheck = checkMemoryWriteAccess(record, writeCtx);
   645|      if (!writeCheck.allowed) {
   646|        return { ok: false as const, error: `Write denied: ${writeCheck.reason}` };
   647|      }
   648|    }
   649|
   650|    const now = nowIso();
   651|    const updated: ScopedMemoryRecord = {
   652|      ...record,
   653|      revoked: true,
   654|      revokedAt: now,
   655|      revokedBy,
   656|      updatedAt: now,
   657|    };
   658|    records[index] = updated;
   659|    await writeState(records);
   660|    await appendEvent({ type: 'revoke', id, revokedBy, at: now });
   661|    return { ok: true as const, record: updated };
   662|  });
   663|}
   664|
   665|// ─── Stale Source File Rejection ──────────────────────────────────
   666|
   667|/**
   668| * Check if a source-file-backed memory record is stale (source commit SHA
   669| * does not match the current commit). Stale source files are rejected.
   670| */
   671|export function isStaleSourceRecord(
   672|  record: ScopedMemoryRecord,
   673|  currentCommitSha: string,
   674|): boolean {
   675|  if (!record.sourceFilePath || !record.sourceCommitSha) return false;
   676|  return record.sourceCommitSha !== currentCommitSha;
   677|}
   678|
   679|/**
   680| * Filter out stale source-file-backed records.
   681| */
   682|export function rejectStaleSourceRecords(
   683|  records: readonly ScopedMemoryRecord[],
   684|  currentCommitSha: string,
   685|): { fresh: ScopedMemoryRecord[]; staleCount: number } {
   686|  const fresh: ScopedMemoryRecord[] = [];
   687|  let staleCount = 0;
   688|  for (const record of records) {
   689|    if (isStaleSourceRecord(record, currentCommitSha)) {
   690|      staleCount++;
   691|    } else {
   692|      fresh.push(record);
   693|    }
   694|  }
   695|  return { fresh, staleCount };
   696|}
   697|
   698|// ─── Irrelevant Conversation History Exclusion ────────────────────
   699|
   700|/**
   701| * Exclude irrelevant conversation history — only include messages that match
   702| * the current task keywords or are from the current task scope.
   703| */
   704|export function excludeIrrelevantHistory(
   705|  records: readonly ScopedMemoryRecord[],
   706|  taskKeywords: string[],
   707|): ScopedMemoryRecord[] {
   708|  if (taskKeywords.length === 0) return [...records];
   709|  const lowerKeywords = taskKeywords.map((k) => k.toLowerCase());
   710|  return records.filter((r) => {
   711|    // Always keep non-conversation records.
   712|    if (r.kind !== 'execution_state' && r.kind !== 'tool_result') return true;
   713|    const content = r.content.toLowerCase();
   714|    return lowerKeywords.some((kw) => content.includes(kw));
   715|  });
   716|}
   717|
   718|// ─── Context Package Builder ──────────────────────────────────────
   719|
   720|export type ScopedContextPackage = {
   721|  records: ScopedMemoryRecord[];
   722|  totalRetrieved: number;
   723|  deniedCount: number;
   724|  staleCount: number;
   725|  sources: string[];
   726|  builtAt: string;
   727|  marker: string;
   728|};
   729|
   730|/**
   731| * Build a scoped context package for an agent — retrieves relevant memory
   732| * across all 4 layers with isolation enforcement, stale rejection, and
   733| * irrelevant-history exclusion.
   734| */
   735|export async function buildScopedContextPackage(
   736|  accessCtx: MemoryAccessContext,
   737|  options: {
   738|    taskId?: string;
   739|    taskKeywords?: string[];
   740|    currentCommitSha?: string;
   741|    search?: string;
   742|    limit?: number;
   743|  } = {},
   744|): Promise<ScopedContextPackage> {
   745|  const taskId = options.taskId ?? accessCtx.taskId ?? '';
   746|
   747|  // Retrieve task memory (scoped to the current task).
   748|  const taskResult = taskId
   749|    ? await retrieveScopedMemory(
   750|        { layer: 'task', scopeId: taskId, limit: 50, search: options.search },
   751|        accessCtx,
   752|      )
   753|    : { records: [], denied: 0 };
   754|
   755|  // Retrieve agent memory (scoped to the current agent — isolation enforced).
   756|  const agentResult = await retrieveScopedMemory(
   757|    { layer: 'agent', scopeId: accessCtx.agentId, limit: 30, search: options.search },
   758|    accessCtx,
   759|  );
   760|
   761|  // Retrieve company memory (scoped to the current company — isolation enforced).
   762|  const companyResult = accessCtx.companyId
   763|    ? await retrieveScopedMemory(
   764|        { layer: 'company', scopeId: accessCtx.companyId, limit: 30, search: options.search },
   765|        accessCtx,
   766|      )
   767|    : { records: [], denied: 0 };
   768|
   769|  // Retrieve enterprise memory (global, read-only).
   770|  const enterpriseResult = await retrieveScopedMemory(
   771|    { layer: 'enterprise', limit: 20, search: options.search },
   772|    accessCtx,
   773|  );
   774|
   775|  let allRecords = [
   776|    ...taskResult.records,
   777|    ...agentResult.records,
   778|    ...companyResult.records,
   779|    ...enterpriseResult.records,
   780|  ];
   781|
   782|  // Reject stale source files.
   783|  let staleCount = 0;
   784|  if (options.currentCommitSha) {
   785|    const { fresh, staleCount: sc } = rejectStaleSourceRecords(allRecords, options.currentCommitSha);
   786|    allRecords = fresh;
   787|    staleCount = sc;
   788|  }
   789|
   790|  // Exclude irrelevant conversation history.
   791|  if (options.taskKeywords && options.taskKeywords.length > 0) {
   792|    allRecords = excludeIrrelevantHistory(allRecords, options.taskKeywords);
   793|  }
   794|
   795|  // Apply limit.
   796|  const limit = options.limit ?? 100;
   797|  allRecords = allRecords.slice(0, limit);
   798|
   799|  // Extract unique sources — every retrieved item must include its source.
   800|  const sources = [...new Set(allRecords.map((r) => r.sourceLabel))];
   801|
   802|  const totalDenied = taskResult.denied + agentResult.denied + companyResult.denied + enterpriseResult.denied;
   803|
   804|  return {
   805|    records: allRecords,
   806|    totalRetrieved: allRecords.length,
   807|    deniedCount: totalDenied,
   808|    staleCount,
   809|    sources,
   810|    builtAt: nowIso(),
   811|    marker: IVX_SCOPED_MEMORY_MARKER,
   812|  };
   813|}
   814|
   815|// ─── Summary ──────────────────────────────────────────────────────
   816|
   817|export type ScopedMemorySummary = {
   818|  marker: string;
   819|  total: number;
   820|  byLayer: Record<MemoryLayer, number>;
   821|  revokedCount: number;
   822|  supersededCount: number;
   823|  expiredCount: number;
   824|  lastUpdatedAt: string | null;
   825|};
   826|
   827|export async function summarizeScopedMemory(): Promise<ScopedMemorySummary> {
   828|  const records = await readState();
   829|  const now = new Date();
   830|
   831|  const byLayer: Record<MemoryLayer, number> = {
   832|    task: 0,
   833|    agent: 0,
   834|    company: 0,
   835|    enterprise: 0,
   836|  };
   837|
   838|  for (const r of records) {
   839|    byLayer[r.layer] = (byLayer[r.layer] ?? 0) + 1;
